type Filters = { tenantId: string; status: 'open' | 'closed'; page: number }

function Orders({ filters }: { filters: Filters }) {
  return useQuery({
    queryKey: ['orders', { status: filters.status, page: filters.page }],
    queryFn: () => fetchOrders(filters),
  })
}

const mutation = useMutation({
  mutationFn: addTodo,
  onMutate: (todo) => {
    client.setQueryData(['todos'], (old: Todo[] = []) => [...old, todo])
  },
  onError: () => client.invalidateQueries({ queryKey: ['todos'] }),
})

getPosts: build.query<Post[], void>({
  query: () => '/posts',
  providesTags: ['Post'],
}),
getPost: build.query<Post, number>({
  query: (id) => `/posts/${id}`,
  providesTags: (result, error, id) => [{ type: 'Post', id }],
}),
addPost: build.mutation<Post, NewPost>({
  query: (body) => ({ url: '/posts', method: 'POST', body }),
  invalidatesTags: ['Post'],
}),
